-- ============================================================================ -- V3__bot_binding.sql - 微信 iLink Bot 多绑定表 -- -- 对应实体：com.chua.starter.ai.support.entity.SysAiBotBinding -- 说明：主键 BIGINT 自增；字段以表名前缀；继承 SysBase 审计字段。 -- ============================================================================  CREATE TABLE IF NOT EXISTS `sys_ai_bot_binding` (     `sys_ai_bot_binding_id`               BIGINT       NOT NULL AUTO_INCREMENT COMMENT '绑定 ID',     `sys_ai_bot_binding_user_id`          BIGINT       NULL COMMENT '关联用户 ID',     `sys_ai_bot_binding_bot_id`          VARCHAR(128) NULL COMMENT 'Bot 唯一标识（iLink 分配的 botId）',     `sys_ai_bot_binding_bot_token`       VARCHAR(512) NULL COMMENT '登录凭证 Token',     `sys_ai_bot_binding_platform`        VARCHAR(32)  NULL COMMENT '平台类型（wechat / wecom）',     `sys_ai_bot_binding_nickname`        VARCHAR(128) NULL COMMENT 'Bot 昵称（来自微信资料）',     `sys_ai_bot_binding_avatar_url`      VARCHAR(512) NULL COMMENT '头像地址',     `sys_ai_bot_binding_gateway_port`    INT          NULL COMMENT '独立网关端口号',     `sys_ai_bot_binding_status`          VARCHAR(32)  NULL DEFAULT 'offline' COMMENT '状态：online / offline / expired',     `sys_ai_bot_binding_bind_source`     VARCHAR(32)  NULL COMMENT '绑定来源（qrcode_scan / manual_import）',     `sys_ai_bot_binding_thinking`        TINYINT      NOT NULL DEFAULT 0 COMMENT '是否启用深度思考（默认关闭）',     `sys_ai_bot_binding_thinking_effort` VARCHAR(16)  NULL COMMENT '深度思考强度（low / medium / high）',     `sys_ai_bot_binding_system_prompt`   TEXT         NULL COMMENT '系统提示词（AI 回复时注入的 system prompt）',     `sys_ai_bot_binding_last_active_time` DATETIME     NULL COMMENT '最后活跃时间',     `create_name`                         VARCHAR(64)  NULL COMMENT '创建人姓名',     `create_by`                           INT          NULL COMMENT '创建人',     `create_time`                         DATETIME     NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',     `update_name`                         VARCHAR(64)  NULL COMMENT '更新人姓名',     `update_by`                           INT          NULL COMMENT '更新人',     `update_time`                         DATETIME     NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',     PRIMARY KEY (`sys_ai_bot_binding_id`),     KEY `idx_sys_ai_bot_binding_bot_id` (`sys_ai_bot_binding_bot_id`) );  -- ============================================================================ -- sys_ai_pricing - AI 定价表（字段对齐 SysAiPricing 实体） -- ============================================================================  CREATE TABLE IF NOT EXISTS `sys_ai_pricing` (     `sys_ai_pricing_id`                  BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键 ID',     `sys_ai_pricing_provider`            VARCHAR(64)  NULL COMMENT '服务商',     `sys_ai_pricing_model`              VARCHAR(128) NULL COMMENT '模型名称',     `sys_ai_pricing_input_price_per_1k`  DOUBLE       NULL COMMENT '输入价格（每 1k tokens，单位元）',     `sys_ai_pricing_output_price_per_1k` DOUBLE      NULL COMMENT '输出价格（每 1k tokens，单位元）',     `sys_ai_pricing_currency`           VARCHAR(8)   NULL COMMENT '币种：CNY / USD',     `sys_ai_pricing_effective_date`     DATETIME     NULL COMMENT '生效日期',     `sys_ai_pricing_source`             VARCHAR(32)  NULL COMMENT '来源：manual / sync',     `create_name`                        VARCHAR(64)  NULL COMMENT '创建人姓名',     `create_by`                          INT          NULL COMMENT '创建人',     `create_time`                        DATETIME     NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',     `update_name`                        VARCHAR(64)  NULL COMMENT '更新人姓名',     `update_by`                          INT          NULL COMMENT '更新人',     `update_time`                        DATETIME     NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',     PRIMARY KEY (`sys_ai_pricing_id`) );  -- ============================================================================ -- sys_ai_usage - AI 用量记录表（字段对齐 SysAiUsage 实体） -- ============================================================================  CREATE TABLE IF NOT EXISTS `sys_ai_usage` (     `sys_ai_usage_id`                   BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键 ID',     `sys_ai_usage_group_name`           VARCHAR(32)  NULL COMMENT '分组：chat / image / video / colorize / vision / rag',     `sys_ai_usage_provider`            VARCHAR(64)  NULL COMMENT '服务商：openai / zhipu / baidu 等',     `sys_ai_usage_model`               VARCHAR(128) NULL COMMENT '模型名称',     `sys_ai_usage_call_type`           VARCHAR(16)  NULL COMMENT '调用类型：sync / async',     `sys_ai_usage_prompt_tokens`        INT          NULL COMMENT '输入 Token 数',     `sys_ai_usage_completion_tokens`    INT          NULL COMMENT '输出 Token 数',     `sys_ai_usage_total_tokens`        INT          NULL COMMENT '总 Token 数',     `sys_ai_usage_input_cost`          DOUBLE       NULL COMMENT '输入费用（单位：元）',     `sys_ai_usage_output_cost`         DOUBLE       NULL COMMENT '输出费用（单位：元）',     `sys_ai_usage_total_cost`          DOUBLE       NULL COMMENT '总费用（单位：元）',     `sys_ai_usage_request_id`          VARCHAR(128) NULL COMMENT '请求 ID（关联调用日志）',     `sys_ai_usage_user_id`             VARCHAR(64)  NULL COMMENT '用户标识（可选）',     `sys_ai_usage_call_time`           DATETIME     NULL COMMENT '调用时间',     `create_name`                       VARCHAR(64)  NULL COMMENT '创建人姓名',     `create_by`                         INT          NULL COMMENT '创建人',     `create_time`                       DATETIME     NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',     `update_name`                       VARCHAR(64)  NULL COMMENT '更新人姓名',     `update_by`                         INT          NULL COMMENT '更新人',     `update_time`                       DATETIME     NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',     PRIMARY KEY (`sys_ai_usage_id`),     KEY `idx_sys_ai_usage_request_id` (`sys_ai_usage_request_id`) );  -- ============================================================================ -- sys_ai_usage_daily - AI 用量日汇总表（字段对齐 SysAiUsageDaily 实体） -- ============================================================================  CREATE TABLE IF NOT EXISTS `sys_ai_usage_daily` (     `sys_ai_usage_daily_id`                     BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键 ID',     `sys_ai_usage_daily_stat_date`              DATE         NULL COMMENT '统计日期',     `sys_ai_usage_daily_group_name`            VARCHAR(32)  NULL COMMENT '分组',     `sys_ai_usage_daily_provider`              VARCHAR(64)  NULL COMMENT '服务商',     `sys_ai_usage_daily_model`                 VARCHAR(128) NULL COMMENT '模型',     `sys_ai_usage_daily_total_calls`           INT          NULL COMMENT '总调用次数',     `sys_ai_usage_daily_total_prompt_tokens`   INT          NULL COMMENT '总输入 Token',     `sys_ai_usage_daily_total_completion_tokens` INT       NULL COMMENT '总输出 Token',     `sys_ai_usage_daily_total_tokens`         INT          NULL COMMENT '总 Token',     `sys_ai_usage_daily_total_cost`           DOUBLE       NULL COMMENT '总费用（元）',     `create_name`                               VARCHAR(64)  NULL COMMENT '创建人姓名',     `create_by`                                 INT          NULL COMMENT '创建人',     `create_time`                               DATETIME     NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',     `update_name`                               VARCHAR(64)  NULL COMMENT '更新人姓名',     `update_by`                                 INT          NULL COMMENT '更新人',     `update_time`                               DATETIME     NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',     PRIMARY KEY (`sys_ai_usage_daily_id`) );